'use client';

import { useState } from 'react';

import { useAutoplay } from '@/registry/ndeko/hooks/use-autoplay';
import { PRESS_LEAD_MS, usePress } from '@/registry/ndeko/lib/demonstration';
import { ChartBarIcon, InfoIcon } from '@/registry/ndeko/lib/icons';
import { Badge } from '@/registry/ndeko/ui/badge';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import {
  DRAFTS,
  EDIT_BUCKETS,
  EDIT_SHARES,
  FIGURES,
  HANDOFF,
  HANDOFF_BY_WEEKDAY,
  PERIODS,
  REPLY,
  REPLY_TREND,
  REPLY_TREND_MAX,
  SECTION,
  WEEKDAYS,
  type Figure,
  type FigureId,
  type PeriodId,
} from './data';
import { FigureCell } from './figure-cell';
import { PeriodSwitch } from './period-switch';
import { Distribution, TrendLine, WeekdayBars } from './proofs';

const LOOP_AFTER_MS = 2200;

function periodOf(id: PeriodId) {
  const period = PERIODS.find((candidate) => candidate.id === id);
  return period ?? PERIODS[0];
}

function formattedOf(figure: Figure, value: number) {
  const figureText = value.toFixed(figure.fractionDigits);
  return `${figureText}${figure.suffix}`;
}

function minutesOf(value: number) {
  return formattedOf(REPLY, value);
}

function spokenFigureOf(figure: Figure, period: PeriodId) {
  const reading = figure.readings[period];
  const value = formattedOf(figure, reading.value);
  return `${figure.label} ${value}`;
}

function spokenPeriodOf(id: PeriodId) {
  const period = periodOf(id);
  const figures = FIGURES.map((figure) => spokenFigureOf(figure, id));
  const figuresLine = figures.join('. ');
  return `Showing ${period.spoken}. ${figuresLine}`;
}

function trendCaptionOf(pointName: string) {
  const unit = pointName.toLowerCase();
  return `${REPLY.label} by ${unit}, illustrative`;
}

export default function Stats01() {
  const [period, setPeriod] = useState<PeriodId>('90d');
  const [litId, setLitId] = useState<FigureId | null>(null);
  const [message, setMessage] = useState('');
  const { pressed, press } = usePress<PeriodId>();
  const shownPeriod = periodOf(period);
  const pointName = shownPeriod.trendPointName;
  const trendCaption = trendCaptionOf(pointName);

  function resetDemonstration() {
    setPeriod('90d');
    setLitId(null);
  }

  const steps = [
    { after: 2400, run: () => press('12m') },
    { after: PRESS_LEAD_MS, run: () => setPeriod('12m') },
    { after: 2600, run: () => setLitId('handoff') },
    { after: 2600, run: () => setLitId(null) },
    { after: 1400, run: () => press('90d') },
    { after: PRESS_LEAD_MS, run: () => setPeriod('90d') },
    { after: 2600, run: () => setLitId('reply') },
    { after: 2600, run: () => setLitId(null) },
  ];
  const { ref, isAutoplaying } = useAutoplay<HTMLElement>(steps, {
    loopAfter: LOOP_AFTER_MS,
    onReset: resetDemonstration,
  });

  /** A comparison the demonstration showed is not left behind once a person takes over. */
  function isLit(id: FigureId) {
    const isShownByDemonstration = litId === id;
    return isAutoplaying && isShownByDemonstration;
  }

  function pickPeriod(next: PeriodId) {
    setPeriod(next);
    setMessage(spokenPeriodOf(next));
  }

  return (
    <section ref={ref} className='@container'>
      <div className='mx-auto flex max-w-6xl flex-col gap-10 px-4 py-16 @2xl:px-6 @2xl:py-24 @5xl:px-8'>
        <header className='flex flex-wrap items-end justify-between gap-x-6 gap-y-4'>
          <div className='flex max-w-2xl flex-col gap-3'>
            <p className='text-primary-ink flex items-center gap-1.5 text-[13px] font-medium'>
              <ChartBarIcon className='size-4' />
              {SECTION.label}
            </p>
            <h2 className='text-2xl font-semibold text-balance @2xl:text-3xl'>
              {SECTION.title}
            </h2>
            <p className='text-muted-foreground text-base text-pretty'>
              {SECTION.lead}
            </p>
          </div>
          <div className='flex flex-wrap items-center gap-2'>
            <PeriodSwitch
              value={period}
              pressed={pressed}
              onValueChange={pickPeriod}
            />
            <Badge variant='secondary'>Illustrative</Badge>
          </div>
        </header>
        <div className='flex flex-col gap-4'>
          <div className='grid gap-3 @xl:grid-cols-2 @4xl:grid-cols-4'>
            <FigureCell
              figure={REPLY}
              reading={REPLY.readings[period]}
              isLit={isLit('reply')}
              className='@xl:col-span-2'
            >
              <TrendLine
                values={REPLY_TREND[period]}
                max={REPLY_TREND_MAX}
                caption={trendCaption}
                pointName={pointName}
                formatValue={minutesOf}
              />
            </FigureCell>
            <FigureCell
              figure={HANDOFF}
              reading={HANDOFF.readings[period]}
              isLit={isLit('handoff')}
            >
              <WeekdayBars
                values={HANDOFF_BY_WEEKDAY[period]}
                days={WEEKDAYS}
                caption={`${HANDOFF.label} by day of the week, illustrative`}
              />
            </FigureCell>
            <FigureCell
              figure={DRAFTS}
              reading={DRAFTS.readings[period]}
              isLit={isLit('drafts')}
            >
              <Distribution
                values={EDIT_SHARES[period]}
                buckets={EDIT_BUCKETS}
                caption='Words changed before a draft is sent, illustrative'
              />
            </FigureCell>
          </div>
          <p className='text-muted-foreground flex items-start gap-1.5 text-xs text-pretty'>
            <InfoIcon className='mt-px size-3.5 shrink-0' />
            {SECTION.source}
          </p>
        </div>
      </div>
      <LiveRegion message={message} />
    </section>
  );
}

'use client';

import { useId } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { cn } from '@/registry/ndeko/lib/utils';

import type { Figure, Reading } from './data';

const DETAIL =
  'text-muted-foreground transition-opacity duration-150 group-hover/figure:opacity-0 group-focus-visible/figure:opacity-0 group-data-[lit=true]/figure:opacity-0';

const CONTEXT =
  'text-foreground opacity-0 transition-opacity duration-150 group-hover/figure:opacity-100 group-focus-visible/figure:opacity-100 group-data-[lit=true]/figure:opacity-100';

function formatOf(fractionDigits: number): Intl.NumberFormatOptions {
  return {
    minimumFractionDigits: fractionDigits,
    maximumFractionDigits: fractionDigits,
  };
}

type FigureCellProps = {
  figure: Figure;
  reading: Reading;
  /** The demonstration shows the comparison as a hover would. */
  isLit: boolean;
  className?: string;
  children: React.ReactNode;
};

export function FigureCell({
  figure,
  reading,
  isLit,
  className,
  children,
}: FigureCellProps) {
  const labelId = useId();
  const valueId = useId();
  const contextId = useId();
  const nameIds = `${labelId} ${valueId}`;
  const format = formatOf(figure.fractionDigits);

  return (
    <div
      role='group'
      tabIndex={0}
      aria-labelledby={nameIds}
      aria-describedby={contextId}
      data-lit={isLit}
      className={cn(
        'group/figure bg-foreground/[0.03] hover:bg-foreground/[0.05] focus-visible:ring-ring/25 data-[lit=true]:bg-foreground/[0.05] flex min-w-0 flex-col justify-between gap-8 rounded-2xl p-5 transition-colors duration-150 outline-none focus-visible:ring-[3px] @2xl:p-6',
        className
      )}
    >
      <div className='flex flex-col gap-2'>
        <p
          id={labelId}
          className='text-muted-foreground text-[13px] font-medium'
        >
          {figure.label}
        </p>
        <span id={valueId} className='flex'>
          <MotionNumber
            value={reading.value}
            format={format}
            suffix={figure.suffix}
            className='text-4xl font-semibold @5xl:text-5xl'
          />
        </span>
        <div className='grid text-[13px] leading-5 *:col-start-1 *:row-start-1'>
          <p className={DETAIL}>{figure.detail}</p>
          <p id={contextId} className={CONTEXT}>
            {reading.context}
          </p>
        </div>
      </div>
      {children}
    </div>
  );
}

'use client';

import { motion, type Transition } from 'motion/react';
import type { CSSProperties } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { EASE_OUT_STRONG, INSTANT } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';

const GLIDE: Transition = { duration: 0.5, ease: EASE_OUT_STRONG };

const PLOT = {
  width: 320,
  height: 72,
  top: 6,
  bottom: 2,
};

const VIEW_BOX = `0 0 ${PLOT.width} ${PLOT.height}`;

const BASELINE_Y = PLOT.height - 0.5;

function easedOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return 'transition-none';
  }
  return 'transition-transform duration-500 ease-(--ease-out-strong)';
}

function glideOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return GLIDE;
}

function plotHeightOf() {
  const margins = PLOT.top + PLOT.bottom;
  return PLOT.height - margins;
}

type Point = { x: number; y: number };

function pointsOf(values: readonly number[], max: number): Point[] {
  const lastPosition = values.length - 1;
  const lastIndex = Math.max(1, lastPosition);
  const plotHeight = plotHeightOf();
  return values.map((value, index) => {
    const share = index / lastIndex;
    const x = share * PLOT.width;
    const level = value / max;
    const drop = 1 - level;
    const offset = drop * plotHeight;
    const y = PLOT.top + offset;
    return { x, y };
  });
}

function commandOf(index: number) {
  if (index === 0) {
    return 'M';
  }
  return 'L';
}

function segmentOf(point: Point, index: number) {
  const x = point.x.toFixed(2);
  const y = point.y.toFixed(2);
  const command = commandOf(index);
  return `${command} ${x} ${y}`;
}

/** Every period has as many points, so the two outlines share one structure and the path can glide. */
function linePathOf(points: Point[]) {
  const segments = points.map((point, index) => segmentOf(point, index));
  return segments.join(' ');
}

function areaPathOf(line: string) {
  return `${line} L ${PLOT.width} ${PLOT.height} L 0 ${PLOT.height} Z`;
}

function rowNameOf(pointName: string, index: number) {
  const position = index + 1;
  return `${pointName} ${position}`;
}

type TrendLineProps = {
  values: readonly number[];
  max: number;
  caption: string;
  pointName: string;
  formatValue: (value: number) => string;
};

export function TrendLine({
  values,
  max,
  caption,
  pointName,
  formatValue,
}: TrendLineProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const transition = glideOf(shouldReduceMotion);
  const points = pointsOf(values, max);
  const line = linePathOf(points);
  const area = areaPathOf(line);

  return (
    <div className='relative'>
      <svg
        viewBox={VIEW_BOX}
        preserveAspectRatio='none'
        aria-hidden='true'
        className='h-16 w-full overflow-visible'
      >
        <line
          x1={0}
          x2={PLOT.width}
          y1={BASELINE_Y}
          y2={BASELINE_Y}
          strokeWidth={1}
          vectorEffect='non-scaling-stroke'
          className='stroke-border'
        />
        <motion.path
          initial={false}
          animate={{ d: area }}
          transition={transition}
          className='fill-primary/10'
        />
        <motion.path
          initial={false}
          animate={{ d: line }}
          transition={transition}
          fill='none'
          strokeWidth={2}
          strokeLinecap='round'
          strokeLinejoin='round'
          vectorEffect='non-scaling-stroke'
          className='stroke-primary'
        />
      </svg>
      <div className='sr-only'>
        <table>
          <caption>{caption}</caption>
          <tbody>
            {values.map((value, index) => (
              <tr key={index}>
                <th scope='row'>{rowNameOf(pointName, index)}</th>
                <td>{formatValue(value)}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function barStyleOf(percent: number): CSSProperties {
  const share = percent / 100;
  return { transform: `scaleY(${share})` };
}

type WeekdayBarsProps = {
  values: readonly number[];
  days: readonly string[];
  caption: string;
};

export function WeekdayBars({ values, days, caption }: WeekdayBarsProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const eased = easedOf(shouldReduceMotion);

  return (
    <div className='relative flex flex-col gap-1.5'>
      <div aria-hidden='true' className='flex h-16 items-end gap-1.5'>
        {values.map((value, index) => (
          <span
            key={days[index]}
            style={barStyleOf(value)}
            className={cn(
              'bg-primary h-full flex-1 origin-bottom rounded-[3px]',
              eased
            )}
          />
        ))}
      </div>
      <div aria-hidden='true' className='flex gap-1.5'>
        {days.map((day) => (
          <span
            key={day}
            className='text-muted-foreground flex-1 text-center text-[10px]'
          >
            {day.charAt(0)}
          </span>
        ))}
      </div>
      <div className='sr-only'>
        <table>
          <caption>{caption}</caption>
          <tbody>
            {values.map((value, index) => (
              <tr key={days[index]}>
                <th scope='row'>{days[index]}</th>
                <td>{value}%</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

function fillStyleOf(percent: number): CSSProperties {
  const share = percent / 100;
  return { transform: `scaleX(${share})` };
}

type DistributionProps = {
  values: readonly number[];
  buckets: readonly string[];
  caption: string;
};

export function Distribution({ values, buckets, caption }: DistributionProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const eased = easedOf(shouldReduceMotion);

  return (
    <div className='relative'>
      <ul aria-hidden='true' className='flex flex-col gap-2'>
        {values.map((value, index) => (
          <li
            key={buckets[index]}
            className='grid grid-cols-[6.5rem_minmax(0,1fr)_2.25rem] items-center gap-2 text-xs'
          >
            <span className='text-muted-foreground truncate'>
              {buckets[index]}
            </span>
            <span className='bg-foreground/[0.06] relative h-1.5 overflow-hidden rounded-full'>
              <span
                style={fillStyleOf(value)}
                className={cn(
                  'bg-primary absolute inset-0 origin-left rounded-full',
                  eased
                )}
              />
            </span>
            <span className='text-end tabular-nums'>{value}%</span>
          </li>
        ))}
      </ul>
      <div className='sr-only'>
        <table>
          <caption>{caption}</caption>
          <tbody>
            {values.map((value, index) => (
              <tr key={buckets[index]}>
                <th scope='row'>{buckets[index]}</th>
                <td>{value}%</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

'use client';

import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';
import { ToggleGroup, ToggleGroupItem } from '@/registry/ndeko/ui/toggle-group';

import { PERIODS, type PeriodId } from './data';

const THUMB =
  'bg-card shadow-[0_1px_2px_rgb(0_0_0/0.08)] hairline-ring ring-foreground/10 dark:bg-foreground/[0.09] dark:ring-foreground/15';

type PeriodSwitchProps = {
  value: PeriodId;
  pressed: PeriodId | null;
  onValueChange: (period: PeriodId) => void;
};

export function PeriodSwitch({
  value,
  pressed,
  onValueChange,
}: PeriodSwitchProps) {
  const pressedValues = [value];

  /** Pressing the period already shown would leave nothing pressed: it stays. */
  function change(nextValues: unknown[]) {
    const [nextValue] = nextValues;
    const period = PERIODS.find((candidate) => candidate.id === nextValue);
    if (period) {
      onValueChange(period.id);
    }
  }

  return (
    <ToggleGroup
      aria-label='Period of the figures'
      value={pressedValues}
      onValueChange={change}
      travel
      size='sm'
      indicatorClassName={THUMB}
      className='bg-foreground/[0.05] rounded-lg p-0.5'
    >
      {PERIODS.map((period) => (
        <ToggleGroupItem
          key={period.id}
          value={period.id}
          className={cn(
            'h-7 rounded-md px-2.5 text-xs',
            pressedQuietOf(pressed === period.id)
          )}
        >
          {period.label}
        </ToggleGroupItem>
      ))}
    </ToggleGroup>
  );
}

export type PeriodId = '90d' | '12m';

export type Period = {
  id: PeriodId;
  label: string;
  spoken: string;
  trendPointName: string;
};

export const PERIODS: Period[] = [
  {
    id: '90d',
    label: 'Last 90 days',
    spoken: 'the last 90 days',
    trendPointName: 'Week',
  },
  {
    id: '12m',
    label: 'Last 12 months',
    spoken: 'the last 12 months',
    trendPointName: 'Month',
  },
];

export type Reading = {
  value: number;
  context: string;
};

export type FigureId = 'reply' | 'handoff' | 'drafts';

export type Figure = {
  id: FigureId;
  label: string;
  detail: string;
  suffix: string;
  fractionDigits: number;
  readings: Record<PeriodId, Reading>;
};

export const SECTION = {
  label: 'In numbers',
  title: 'What changes when every reply arrives drafted',
  lead: 'Three figures from support teams on Tidewell, each with what sits behind it.',
  source:
    'Source: replace with the report these figures come from and its dates. Every figure here is illustrative.',
};

/** Invented figures. Each headline value agrees with the proof drawn under it. */
export const REPLY: Figure = {
  id: 'reply',
  label: 'Median first reply',
  detail:
    'From the moment a ticket arrives to the first answer the customer reads',
  suffix: ' min',
  fractionDigits: 1,
  readings: {
    '90d': { value: 3.8, context: 'Down from 5.0 min in the 90 days before' },
    '12m': {
      value: 5.6,
      context: 'Down from 11.6 min in the 12 months before',
    },
  },
};

export const HANDOFF: Figure = {
  id: 'handoff',
  label: 'Resolved without a handoff',
  detail: 'Tickets closed by the first person who opened them',
  suffix: '%',
  fractionDigits: 0,
  readings: {
    '90d': { value: 68, context: 'Up from 61% in the 90 days before' },
    '12m': { value: 59, context: 'Up from 44% in the 12 months before' },
  },
};

export const DRAFTS: Figure = {
  id: 'drafts',
  label: 'Drafts sent as written',
  detail: 'Replies sent without a word changed, out of every reply drafted',
  suffix: '%',
  fractionDigits: 0,
  readings: {
    '90d': { value: 81, context: 'Up from 70% in the 90 days before' },
    '12m': { value: 74, context: 'Up from 52% in the first month' },
  },
};

export const FIGURES: Figure[] = [REPLY, HANDOFF, DRAFTS];

/** Median first reply in minutes: one point a week over 90 days, one a month over 12 months. */
export const REPLY_TREND: Record<PeriodId, number[]> = {
  '90d': [4.6, 4.4, 4.3, 4.1, 4.0, 3.9, 3.8, 3.8, 3.7, 3.6, 3.5, 3.4],
  '12m': [8.9, 8.1, 7.2, 6.5, 6.0, 5.7, 5.4, 5.0, 4.6, 4.3, 4.0, 3.8],
};

export const REPLY_TREND_MAX = 10;

export const WEEKDAYS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

/** Share of tickets resolved without a handoff, by day of the week. Their mean is the headline. */
export const HANDOFF_BY_WEEKDAY: Record<PeriodId, number[]> = {
  '90d': [67, 71, 72, 70, 69, 65, 62],
  '12m': [58, 61, 62, 60, 59, 56, 57],
};

export const EDIT_BUCKETS = [
  'No change',
  '1 to 5 words',
  '6 to 20 words',
  'Rewritten',
];

/** How much people change a draft before sending it. The first bucket is the headline. */
export const EDIT_SHARES: Record<PeriodId, number[]> = {
  '90d': [81, 12, 5, 2],
  '12m': [74, 15, 7, 4],
};
